WITH with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT island_id, AVG(island_id) AS avg_island_id, COUNT(*) AS event_count, COUNT(*) AS row_count, SUM(CASE WHEN device_code = 'DV-01' THEN is_new_session ELSE 0 END) AS dv_01_is_new_session, APPROX_PERCENTILE(status_bits, ARRAY(0.25, 0.5, 0.75)) AS status_bits_quartiles FROM sessions_device_readings GROUP BY 1 HAVING avg_island_id < 0 ORDER BY event_count
